'use client'

import { useState } from 'react'

export default function FacilityImage({ src, alt, className, ...props }) {
    const [error, setError] = useState(false)

    if (error) {
        return (
            <div className={`${className} bg-gray-200 h-full w-full flex items-center justify-center`}>
                <div className="text-center text-gray-400">
                    <svg className="w-12 h-30 mx-auto mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                    </svg>
                    <p className="text-sm">Image not available</p>
                </div>
            </div>
        )
    }

    return (
        <img
            src={src}
            alt={alt}
            className={className}
            onError={() => setError(true)}
            {...props}
        />
    )
}